    AND statement_tex IS 'Let $\psi$ be a primitive character and $0 < \theta < 1$. Suppose that for every $Y_0 \ge 1$ there is $Y \ge Y_0$ with
\[ \mathcal G_\psi(x) \le x^\theta \qquad \text{for all } x \in [Y, Y^{3/2}]. \]
Let $A_k$ be the \hyperref[TQ4B]{Taylor coefficients} of $\mathcal H_\psi$. Then there is $\sigma_0 > 2$ such that for every real $\sigma \ge \sigma_0$ there are a constant $C > 0$ and an infinite set $K$ of positive integers with
\[ \text{for all } k \in K \text{ and all } \tau \in \R: \qquad |A_k(\sigma + i\tau)| + \Re A_k(\sigma) \le C\,(\sigma - \theta)^{-k}. \]')
  OR NOT EXISTS (SELECT 1 FROM proofs WHERE id = 109 AND revision = 14
    AND body_tex IS 'Put $g(u) = \mathcal G_\psi(e^u)$, a real function, and $g_+ = \max(g, 0)$. Let $\sigma_0 = 200$, as in the \hyperref[8JT4]{concentration of the kernel}, and fix a real $\sigma \ge \sigma_0$. For each $Y \ge 2$ given by the hypothesis put $U = \ln Y$ and
\[ W = [U, \tfrac32 U], \qquad k = \bigl\lceil \tfrac54 \sigma U \bigr\rceil, \qquad K_k(u) = \frac{u^k e^{-\sigma u}}{k!}. \]
Here $W$ is the window $Y \le x \le Y^{3/2}$ in the variable $u = \ln x$, and $k$ puts the peak $u = k/\sigma$ of $K_k$ (see the \hyperref[8JT6]{graphs of $K_k$}) at the midpoint $\frac54 U$ of $W$, up to rounding. As $k$ grows, almost all of the kernel lies in $W$ (see \hyperref[8JT7]{how $K_k$ concentrates in $W$}). Then for every $\tau \in \R$
\begin{alignat*}{2}
|A_k(\sigma + i\tau)| + \Re A_k(\sigma) &\le \int_0^\infty (|g| + g)\, K_k = 2\int_0^\infty g_+ K_k &\qquad& \text{(a)} \\
&\le 2\int_W e^{\theta u} K_k + 2C_\psi \int_{u \notin W} e^{2u} K_k && \text{(b)} \\
&\le 2(\sigma - \theta)^{-k-1} + 4 C_\psi\, \sigma^{-k} && \text{(c)} \\
&\le (2 + 4C_\psi)\, (\sigma - \theta)^{-k}, && \text{(d)}
\end{alignat*}
where:
\begin{itemize}
\item[(a)] \hyperref[8JT3]{$A_k(\sigma + i\tau) = \int_0^\infty g\, K_k\, e^{-i\tau u}\,du$}, with $K_k \ge 0$ and $|e^{-i\tau u}| = 1$;
\item[(b)] $g_+ \le e^{\theta u}$ on $W$ by the hypothesis, and $g_+ \le C_\psi e^{2u}$ everywhere by \ref{8JS3};
\item[(c)] the \hyperref[8JT4]{concentration of the kernel};
\item[(d)] $\sigma \ge \sigma - \theta \ge 1$.
\end{itemize}
Each such $Y$ gives one $k$, and these $Y$ are unbounded, so the set $K$ of these $k$ is infinite. This proves the claim with $C = 2 + 4C_\psi$.')
  OR NOT EXISTS (SELECT 1 FROM proofs WHERE id = 110 AND revision = 1
    AND body_tex IS '\emph{(1)} \textbf{The derivative may be taken under the integral sign.} By \ref{8JS3}, $|g(u)| \le C_\psi e^{2u}$. Hence for $\Re s \ge \sigma_1 > 2$,
\[ \bigl|g(u)\, u^k e^{-su}\bigr| \le C_\psi\, u^k e^{-(\sigma_1 - 2)u}, \]
which is integrable in $u$ and independent of $s$, so dominated convergence applies.

\emph{(2)} \textbf{Each derivative brings down a factor $-u$ from $e^{-su}$.} Starting from $\mathcal H_\psi(s) = \int_0^\infty g(u)\, e^{-su}\,du$,
\begin{align*}
\mathcal H_\psi''(s) &= -\int_0^\infty g(u)\, u\, e^{-su}\,du, \\
\mathcal H_\psi''''(s) &= \int_0^\infty g(u)\, u^2 e^{-su}\,du, \\
\mathcal H_\psi''''''(s) &= -\int_0^\infty g(u)\, u^3 e^{-su}\,du,
\end{align*}
and in general the $k$-th derivative carries $(-u)^k$.')
  OR NOT EXISTS (SELECT 1 FROM results WHERE id = 125 AND revision = 2
    AND statement_tex IS 'For real $\sigma > 2$ and integers $k \ge 0$ let $K_k(u) = u^k e^{-\sigma u}/k!$ for $u \ge 0$.
\begin{enumerate}
\item[(i)] For every real $a < \sigma$, $\displaystyle\int_0^\infty e^{au} K_k(u)\,du = (\sigma - a)^{-k-1}$.
\item[(ii)] Let $\sigma \ge 200$ and $U > 0$, and put $W = [U, \frac32 U]$ and $k = \lceil \frac54 \sigma U \rceil$. Then
\[ \int_{u \notin W} e^{2u} K_k(u)\,du \le 2\sigma^{-k}. \]
\end{enumerate}
See the \hyperref[8JT6]{graphs of $K_k$} and \hyperref[8JT7]{how $K_k$ concentrates in $W$}.')
  OR NOT EXISTS (SELECT 1 FROM proofs WHERE id = 111 AND revision = 3
    AND body_tex IS '\emph{(i)} \textbf{This is a Gamma integral.} Substitute $v = (\sigma - a)u$ in $\int_0^\infty u^k e^{-(\sigma - a)u}\,du$ and use $\int_0^\infty v^k e^{-v}\,dv = k!$.

\emph{(ii)} \textbf{Outside $W$, bound $1$ by an exponential and integrate over all $u$ with (i).} Put $t = \sigma/5$. We use $\frac54 \sigma U \le k < \frac54 \sigma U + 1$ and, since $\sigma \ge 200$,
\[ \frac45 - \frac2\sigma \ge 0.79 > e^{-6/25} \approx 0.787, \qquad \frac65 - \frac2\sigma \ge 1.19 > e^{4/25} \approx 1.174. \]

\emph{Right of $W$.} For $u > \frac32 U$ we have $1 \le e^{t(u - 3U/2)}$. Hence, by (i) with $a = 2 + t < \sigma$,
\begin{align*}
\int_{u > 3U/2} e^{2u} K_k(u)\,du &\le e^{-3tU/2} \int_0^\infty e^{(2+t)u} K_k(u)\,du \\
&= e^{-3\sigma U/10} \Bigl(\frac45 \sigma - 2\Bigr)^{-k-1} \\
&\le e^{6/25}\, e^{-6k/25}\, \sigma^{-k-1} \Bigl(\frac45 - \frac2\sigma\Bigr)^{-k-1} \\
&= \sigma^{-k} \cdot \frac{e^{6/25}}{\frac45 \sigma - 2} \cdot \biggl(\frac{e^{-6/25}}{\frac45 - \frac2\sigma}\biggr)^{k}.
\end{align*}
The third line uses $\frac{3}{10}\sigma U > \frac{6}{25}(k - 1)$. In the last line the middle factor is less than $1$ and the last factor is at most $1$, so the integral is at most $\sigma^{-k}$.

\emph{Left of $W$.} For $u < U$ we have $1 \le e^{t(U - u)}$. Hence, by (i) with $a = 2 - t$,
\begin{align*}
\int_{u < U} e^{2u} K_k(u)\,du &\le e^{tU} \int_0^\infty e^{(2-t)u} K_k(u)\,du \\
&= e^{\sigma U/5} \Bigl(\frac65 \sigma - 2\Bigr)^{-k-1} \\
&\le \sigma^{-k} \cdot \frac{1}{\frac65 \sigma - 2} \cdot \biggl(\frac{e^{4/25}}{\frac65 - \frac2\sigma}\biggr)^{k},
\end{align*}
using $\frac15 \sigma U \le \frac{4}{25} k$. Again both factors after $\sigma^{-k}$ are at most $1$.

Adding the two bounds gives (ii).')
