  OR NOT EXISTS (SELECT 1 FROM proofs WHERE id = 125 AND revision = 2
    AND body_tex IS '\emph{Idea.} Choose $z=\sigma+i\tau$ whose nearest pole is closer to $z$ than any pole is to $\sigma$. The corresponding term of the explicit series dominates both the rest of $A_k(z)$ and the whole of $A_k(\sigma)$.

\emph{(1)} \textbf{The residues in the explicit series are absolutely summable.} Let $P$ consist of the distinct nontrivial zeros of $\zeta$ together with $0$ and the negative even integers. From the \hyperref[8JTA]{formula for $A_k$}, for $\Re z>1$,
$$
A_k(z)=\sum_{p\in P}\frac{c_p}{(z-p)^{k+1}},
$$
where $c_p$ is the residue of $H_{\mathbf 1}$ at $p$. In particular $c_0=\ln 2\pi$, $c_{-2n}=-1/(2n(2n+1))$, and $c_\rho=-m(\rho)/(\rho(\rho-1))$ for a nontrivial zero of multiplicity $m(\rho)$. Thus $B=\sum_{p\in P}|c_p|<\infty$ by absolute convergence of the \hyperref[8JUK]{explicit formula} at $x=1$.

\emph{(2)} \textbf{A point on $\Re z=\sigma$ can get closer to a single pole than $\sigma$ is to any pole.} Fix $\sigma>1$ and let $D=\min_{p\in P}|\sigma-p|$. This minimum exists by local finiteness. Put $a_0=\sigma-\Re\rho_0<\sigma-\theta$. If $a_0<D$, take $p=\rho_0$. If $D\le a_0$, take a pole $p$ at distance $D$ from $\sigma$. Since $D<\sigma$, this $p$ cannot be a nonpositive real pole. It is a nontrivial zero and hence \hyperref[8JUH]{nonreal}, so $\sigma-\Re p<|\sigma-p|=D$. In both cases,
$$
\sigma-\Re p<\min(D,\sigma-\theta).
$$

For $\tau$ in a sufficiently small closed interval of positive length around $\operatorname{Im}p$, we still have $|\sigma+i\tau-p|<\min(D,\sigma-\theta)$. Only finitely many poles can be this close to the resulting compact segment. Two poles with different imaginary parts tie in distance for at most one $\tau$, since the difference of their squared distances is affine with nonzero slope. Two poles with the same imaginary part have different horizontal distances because both lie to the left of the line. Choose $\tau$ in the interval away from the finitely many ties. Then $z=\sigma+i\tau$ has a unique nearest pole $p_*$, at distance $d<\min(D,\sigma-\theta)$.

\emph{(3)} \textbf{Estimate the nearest-pole term, the remaining terms at $z$, and the real-axis contribution separately.}
By local finiteness, the following distances are attained:
$$
r=\min_{p\in P\setminus\{p_*\}}|z-p|,
\qquad D_1=\min_{p\in P\setminus\{0\}}|\sigma-p|.
$$
The nearest pole to $z$ is unique, so $r>d$. Also $D_1\ge D>d$.

\begin{enumerate}
\item[(a)] \textbf{The nearest pole at $z$.} Its contribution has absolute value
$$
\left|\frac{c_{p_*}}{(z-p_*)^{k+1}}\right|
= |c_{p_*}|\,d^{-k-1}.
$$

\item[(b)] \textbf{The other poles at $z$.} Use $|z-p|\ge r$ for every $p\ne p_*$:
\begin{align*}
\left|\sum_{p\ne p_*}\frac{c_p}{(z-p)^{k+1}}\right|
&\le \sum_{p\ne p_*}\frac{|c_p|}{|z-p|^{k+1}}\\
&\le (B-|c_{p_*}|)\,r^{-k-1}.
\end{align*}

\item[(c)] \textbf{The real-axis contribution.} The pole at $0$ contributes $c_0\sigma^{-k-1}>0$. For every other pole, use $\Re w\ge -|w|$ and $|\sigma-p|\ge D_1$:
\begin{align*}
\Re A_k(\sigma)
&\ge c_0\sigma^{-k-1}
 -\sum_{p\ne 0}\frac{|c_p|}{|\sigma-p|^{k+1}}\\
&\ge c_0\sigma^{-k-1}-(B-c_0)\,D_1^{-k-1}.
\end{align*}
\end{enumerate}

Relative to the term in (a), the two possible losses are bounded by
$$
\frac{B-|c_{p_*}|}{|c_{p_*}|}\left(\frac{d}{r}\right)^{k+1},
\qquad
\frac{B-c_0}{|c_{p_*}|}\left(\frac{d}{D_1}\right)^{k+1}.
$$
Both ratios tend to zero. Choose a nonnegative integer $k_0$ so that each is at most $1/4$ for every integer $k\ge k_0$. For these $k$, the reverse triangle inequality and (a)–(c) give
\begin{align*}
|A_k(z)|+\Re A_k(\sigma)
&\ge |c_{p_*}|\,d^{-k-1}-(B-|c_{p_*}|)\,r^{-k-1}\\
&\quad +c_0\sigma^{-k-1}-(B-c_0)\,D_1^{-k-1}\\
&\ge \frac{|c_{p_*}|}{2d}\,d^{-k}+c_0\sigma^{-k-1}.
\end{align*}')
  OR NOT EXISTS (SELECT 1 FROM results WHERE id = 146 AND revision = 1
    AND statement_tex IS 'Let $0<\theta<1$. Suppose that for every real $Y_0\ge 1$ there is a real $Y\ge Y_0$ such that
$$
G_{\mathbf 1}(x)\le x^\theta
\qquad \text{for every } x\in[Y,Y^{3/2}].
$$
Let $A_k$ be the Taylor coefficients of $H_{\mathbf 1}$ in the \hyperref[8JTA]{zeta example}. There is a real $\sigma_0>2$ such that for every real $\sigma\ge\sigma_0$ there are a constant $C>0$ and an infinite set $K$ of positive integers with the following property. For every $k\in K$ and every real $\tau$,
$$
|A_k(\sigma+i\tau)|+\Re A_k(\sigma)\le C(\sigma-\theta)^{-k}.
$$')
  OR NOT EXISTS (SELECT 1 FROM proofs WHERE id = 126 AND revision = 1
    AND body_tex IS 'The \hyperref[8JTA]{explicit formula} gives $|G_{\mathbf 1}(x)|\le Bx$ for some $B>0$ and every $x\ge 1$. Indeed, each power $x^\rho$ has modulus at most $x$, and the coefficients of all the terms are \hyperref[8JUK]{absolutely summable}.

Put $g(u)=G_{\mathbf 1}(e^u)$ and $g_+(u)=\max(g(u),0)$. Let $\sigma_0$ be the threshold in the \hyperref[8JT4]{kernel concentration estimate}, and fix $\sigma\ge\sigma_0$. For each $Y>1$ in the hypothesis put $U=\ln Y$ and choose
$$
W=[U,\tfrac32 U],\qquad k=\bigl\lceil\tfrac54\sigma U\bigr\rceil,
\qquad K_k(u)=\frac{u^k e^{-\sigma u}}{k!}.
$$
This puts the peak of $K_k$ at the midpoint of $W$, up to rounding. By the \hyperref[8JT3]{Laplace integral for the Taylor coefficients},
$A_k(\sigma+i\tau)=\int_0^\infty g(u)K_k(u)e^{-i\tau u}\,du$.
Since $g$ is real, the following holds for every real $\tau$:
\begin{align*}
|A_k(\sigma+i\tau)|+\Re A_k(\sigma)
&\le 2\int_0^\infty g_+(u) K_k(u)\,du \\
&\le 2\int_W e^{\theta u}K_k(u)\,du
  +2B\int_{[0,\infty)\setminus W} e^{2u}K_k(u)\,du \\
&\le 2(\sigma-\theta)^{-k-1}+4B\sigma^{-k} \\
&\le (2+4B)(\sigma-\theta)^{-k}.
\end{align*}
The second line uses the interval bound on $W$ and $|g(u)|\le Be^u\le Be^{2u}$ elsewhere. The third line uses both parts of the kernel estimate. The eligible $Y$ are unbounded, so the resulting set $K$ of integers $k$ is infinite.')
  OR NOT EXISTS (SELECT 1 FROM proofs WHERE id = 127 AND revision = 1
    AND body_tex IS 'Suppose a nontrivial zero has real part greater than $\theta$. Fix a real $\sigma\ge\sigma_0$ as in the \hyperref[8JUP]{one-sided bound}, with constant $C$ and infinite set $K$. The \hyperref[8JUM]{lower bound} gives $\tau$, $c>0$, $0<d<\sigma-\theta$, and $k_0$. For each $k\in K$ with $k\ge k_0$,
$$
c\,d^{-k}\le |A_k(\sigma+i\tau)|+\Re A_k(\sigma)
\le C(\sigma-\theta)^{-k}.
$$
This would bound $\bigl((\sigma-\theta)/d\bigr)^k$ by $C/c$ on an unbounded set of $k$, even though $(\sigma-\theta)/d>1$.');

-- 8JT2 statement
UPDATE results SET statement_tex = 'Let $\psi$ be a primitive character and $0 < \theta < 1$. Suppose that for every $Y_0 \ge 1$ there is $Y \ge Y_0$ with
\[ \mathcal G_\psi(x) \le x^\theta \qquad \text{for all } x \in [Y, Y^{3/2}]. \]
Let $A_k$ be the \hyperref[TQ4B]{Taylor coefficients} of $\mathcal H_\psi$. Then there is $c_0 > 2$ such that for every real $c \ge c_0$ there are a constant $C > 0$ and an infinite set $K$ of positive integers with
\[ \text{for all } k \in K \text{ and all } y \in \R: \qquad |A_k(c+iy)| + \Re A_k(c) \le C\,(c-\theta)^{-k}. \]',
  statement_html_cache = NULL, revision = revision + 1, updated_at = '2026-11-27 20:00:00', updated_by = 'claude'
WHERE id = 123;

-- 8JT2 proof
UPDATE proofs SET body_tex = 'Put $g(u) = \mathcal G_\psi(e^u)$, a real function, and $g_+ = \max(g, 0)$. Let $c_0 = 200$, as in the \hyperref[8JT4]{concentration of the kernel}, and fix a real $c \ge c_0$. For each $Y \ge 2$ given by the hypothesis put $U = \ln Y$ and
\[ W = [U, \tfrac32 U], \qquad k = \bigl\lceil \tfrac54 c U \bigr\rceil, \qquad K_k(u) = \frac{u^k e^{-cu}}{k!}. \]
Here $W$ is the window $Y \le x \le Y^{3/2}$ in the variable $u = \ln x$, and $k$ puts the peak $u = k/c$ of $K_k$ (see the \hyperref[8JT6]{graphs of $K_k$}) at the midpoint $\frac54 U$ of $W$, up to rounding. As $k$ grows, almost all of the kernel lies in $W$ (see \hyperref[8JT7]{how $K_k$ concentrates in $W$}). Then for every $y \in \R$
\begin{alignat*}{2}
|A_k(c+iy)| + \Re A_k(c) &\le \int_0^\infty (|g| + g)\, K_k = 2\int_0^\infty g_+ K_k &\qquad& \text{(a)} \\
&\le 2\int_W e^{\theta u} K_k + 2C_\psi \int_{u \notin W} e^{2u} K_k && \text{(b)} \\
&\le 2(c-\theta)^{-k-1} + 4 C_\psi\, c^{-k} && \text{(c)} \\
&\le (2 + 4C_\psi)\, (c-\theta)^{-k}, && \text{(d)}
\end{alignat*}
where:
\begin{itemize}
\item[(a)] \hyperref[8JT3]{$A_k(c+iy) = \int_0^\infty g\, K_k\, e^{-iyu}\,du$}, with $K_k \ge 0$ and $|e^{-iyu}| = 1$;
\item[(b)] $g_+ \le e^{\theta u}$ on $W$ by the hypothesis, and $g_+ \le C_\psi e^{2u}$ everywhere by \ref{8JS3};
\item[(c)] the \hyperref[8JT4]{concentration of the kernel};
\item[(d)] $c \ge c-\theta \ge 1$.
\end{itemize}
Each such $Y$ gives one $k$, and these $Y$ are unbounded, so the set $K$ of these $k$ is infinite. This proves the claim with $C = 2 + 4C_\psi$.',
  body_html_cache = NULL, revision = revision + 1, updated_at = '2026-11-27 20:00:00', updated_by = 'claude'
WHERE id = 109;

-- 8JT3 proof
UPDATE proofs SET body_tex = '\emph{(1)} \textbf{The derivative may be taken under the integral sign.} By \ref{8JS3}, $|g(u)| \le C_\psi e^{2u}$. Hence for $\Re s \ge c_1 > 2$,
\[ \bigl|g(u)\, u^k e^{-su}\bigr| \le C_\psi\, u^k e^{-(c_1 - 2)u}, \]
which is integrable in $u$ and independent of $s$, so dominated convergence applies.

\emph{(2)} \textbf{Each derivative brings down a factor $-u$ from $e^{-su}$.} Starting from $\mathcal H_\psi(s) = \int_0^\infty g(u)\, e^{-su}\,du$,
\begin{align*}
\mathcal H_\psi''(s) &= -\int_0^\infty g(u)\, u\, e^{-su}\,du, \\
\mathcal H_\psi''''(s) &= \int_0^\infty g(u)\, u^2 e^{-su}\,du, \\
\mathcal H_\psi''''''(s) &= -\int_0^\infty g(u)\, u^3 e^{-su}\,du,
\end{align*}
and in general the $k$-th derivative carries $(-u)^k$.',
  body_html_cache = NULL, revision = revision + 1, updated_at = '2026-11-27 20:00:00', updated_by = 'claude'
WHERE id = 110;

-- 8JT4 statement
UPDATE results SET statement_tex = 'For real $c > 2$ and integers $k \ge 0$ let $K_k(u) = u^k e^{-cu}/k!$ for $u \ge 0$.
\begin{enumerate}
\item[(i)] For every real $a < c$, $\displaystyle\int_0^\infty e^{au} K_k(u)\,du = (c - a)^{-k-1}$.
\item[(ii)] Let $c \ge 200$ and $U > 0$, and put $W = [U, \frac32 U]$ and $k = \lceil \frac54 c U \rceil$. Then
\[ \int_{u \notin W} e^{2u} K_k(u)\,du \le 2c^{-k}. \]
\end{enumerate}
See the \hyperref[8JT6]{graphs of $K_k$} and \hyperref[8JT7]{how $K_k$ concentrates in $W$}.',
  statement_html_cache = NULL, revision = revision + 1, updated_at = '2026-11-27 20:00:00', updated_by = 'claude'
WHERE id = 125;

-- 8JT4 proof
UPDATE proofs SET body_tex = '\emph{(i)} \textbf{This is a Gamma integral.} Substitute $v = (c - a)u$ in $\int_0^\infty u^k e^{-(c - a)u}\,du$ and use $\int_0^\infty v^k e^{-v}\,dv = k!$.

\emph{(ii)} \textbf{Outside $W$, bound $1$ by an exponential and integrate over all $u$ with (i).} Put $t = c/5$. We use $\frac54 c U \le k < \frac54 c U + 1$ and, since $c \ge 200$,
\[ \frac45 - \frac2c \ge 0.79 > e^{-6/25} \approx 0.787, \qquad \frac65 - \frac2c \ge 1.19 > e^{4/25} \approx 1.174. \]

\emph{Right of $W$.} For $u > \frac32 U$ we have $1 \le e^{t(u - 3U/2)}$. Hence, by (i) with $a = 2 + t < c$,
\begin{align*}
\int_{u > 3U/2} e^{2u} K_k(u)\,du &\le e^{-3tU/2} \int_0^\infty e^{(2+t)u} K_k(u)\,du \\
&= e^{-3c U/10} \Bigl(\frac45 c - 2\Bigr)^{-k-1} \\
&\le e^{6/25}\, e^{-6k/25}\, c^{-k-1} \Bigl(\frac45 - \frac2c\Bigr)^{-k-1} \\
&= c^{-k} \cdot \frac{e^{6/25}}{\frac45 c - 2} \cdot \biggl(\frac{e^{-6/25}}{\frac45 - \frac2c}\biggr)^{k}.
\end{align*}
The third line uses $\frac{3}{10}c U > \frac{6}{25}(k - 1)$. In the last line the middle factor is less than $1$ and the last factor is at most $1$, so the integral is at most $c^{-k}$.

\emph{Left of $W$.} For $u < U$ we have $1 \le e^{t(U - u)}$. Hence, by (i) with $a = 2 - t$,
\begin{align*}
\int_{u < U} e^{2u} K_k(u)\,du &\le e^{tU} \int_0^\infty e^{(2-t)u} K_k(u)\,du \\
&= e^{c U/5} \Bigl(\frac65 c - 2\Bigr)^{-k-1} \\
&\le c^{-k} \cdot \frac{1}{\frac65 c - 2} \cdot \biggl(\frac{e^{4/25}}{\frac65 - \frac2c}\biggr)^{k},
\end{align*}
using $\frac15 c U \le \frac{4}{25} k$. Again both factors after $c^{-k}$ are at most $1$.

Adding the two bounds gives (ii).',
  body_html_cache = NULL, revision = revision + 1, updated_at = '2026-11-27 20:00:00', updated_by = 'claude'
WHERE id = 111;

-- 8JT5 statement
UPDATE results SET statement_tex = 'Let $\psi$ be a primitive character and $0 < \theta < 1$. Suppose that some pole $\rho$ of $\mathcal H_\psi$, that is, some $\rho$ in the \hyperref[8JN4]{set of poles} $Z$, satisfies $\Re\rho > \theta$. Let $A_k$ be the \hyperref[TQ4B]{Taylor coefficients} of $\mathcal H_\psi$. Then for every real $c > 1$ there are $y \in \R$, $C_1 > 0$, $0 < d < c-\theta$ and $k_0 \ge 0$ with
\[ \text{for all } k \ge k_0: \qquad |A_k(c+iy)| + \Re A_k(c) \ge C_1\, d^{-k}. \]',
  statement_html_cache = NULL, revision = revision + 1, updated_at = '2026-11-27 20:00:00', updated_by = 'claude'
WHERE id = 136;

-- 8JT5 proof
UPDATE proofs SET body_tex = '\emph{Idea.} $A_k(z)$ is the $k$-th Taylor coefficient of $w \mapsto \mathcal H_\psi(z - w)$. If $z$ has a unique nearest pole, at distance $d$, then $|A_k(z)|$ grows like $d^{-k}$ (Step 1). A pole with $\Re\rho > \theta$ is closer than $c-\theta$ to the line $\Re s=c$; we find a point of that line where it shows up in $A_k$.

\emph{Step 1: Taylor coefficients near a pole.} Let $\Re z > 1$, and let $\overline B(z, r)$ be a closed disc in $\Re s > 0$ that contains exactly one pole $\rho$ of $\mathcal H_\psi$, with residue $\operatorname{Res}_\rho$. Then
\[ A_k(z) = \frac{\operatorname{Res}_\rho}{(z - \rho)^{k+1}} + O(r^{-k}) \qquad (k \to \infty). \]
Indeed, write $\mathcal H_\psi(s) = \frac{\operatorname{Res}_\rho}{s - \rho} + h(s)$ with $h$ holomorphic on a neighbourhood of $\overline B(z, r)$. Since $\frac{d^k}{ds^k}\frac{1}{s - \rho} = \frac{(-1)^k k!}{(s - \rho)^{k+1}}$, the first term contributes $\frac{\operatorname{Res}_\rho}{(z - \rho)^{k+1}}$ to $A_k(z)$, and Cauchy''s estimate gives $\frac{|h^{(k)}(z)|}{k!} \le r^{-k} \max_{|s - z| = r} |h(s)|$. In the same way $A_k(z) = O(r^{-k})$ if $\overline B(z, r)$ contains no pole.

\emph{Step 2: two distances.} Fix $c > 1$, and put $D_* = c-\theta$ and $D = \min_{\rho \in Z} |c - \rho|$, the distance from $c$ to the nearest pole; the minimum exists because $Z$ is nonempty and \hyperref[8JS5]{locally finite}. Every pole is \hyperref[8JN4]{simple with nonzero residue}, and every pole has $\Re\rho < 1 < c$, since $L(s,\chi) \ne 0$ for $\Re s \ge 1$ \cite{Davenport}. By hypothesis some $\rho_0 \in Z$ has $c - \Re\rho_0 < D_*$. All discs below are centred on the line $\Re s=c$ and have radius less than $D_* < c$, so they lie in $\Re s > 0$.

\emph{Case (a): some pole $\rho_1$ has $c - \Re\rho_1 < \min(D, D_*)$.} Choose a closed interval $J$ around $\Im\rho_1$ such that $|c+iy - \rho_1| < \min(D, D_*)$ for all $y \in J$. Only finitely many poles lie within distance $\min(D, D_*)$ of the compact segment $\{c+iy \mid y \in J\}$. Two of them are equidistant from $c+iy$ for at most one $y$: if their imaginary parts differ, equality of the squared distances is a linear equation in $y$ with nonzero slope; if their imaginary parts agree, their real parts differ, and since both lie left of the line their distances to it differ. Choose $y \in J$ avoiding these finitely many values and put $z = c+iy$. Then $z$ has a unique nearest pole $\rho$, at distance $d \le |z - \rho_1| < \min(D, D_*)$. Choose $r$ with $d < r < \min(D, D_*)$ such that $\rho$ is the only pole in $\overline B(z, r)$. The disc $\overline B(c, r)$ contains no pole, as $r < D$. By Step 1,
\begin{align*}
|A_k(z)| + \Re A_k(c) &\ge |A_k(z)| - |A_k(c)| \\
&\ge |\operatorname{Res}_\rho|\, d^{-k-1} - O(r^{-k}) \ge \frac{|\operatorname{Res}_\rho|}{2d}\, d^{-k}
\end{align*}
for all large $k$, because $d < r$. This is the claim with $C_1 = |\operatorname{Res}_\rho|/(2d)$. We cannot simply take $z = c$: there the conjugate poles $\rho_1$ and $\bar\rho_1$ are equally close, and their contributions to $A_k(c)$ may cancel. See the \hyperref[8JT8]{picture of case (a)}.

\emph{Case (b): every pole has $c - \Re\rho \ge \min(D, D_*)$.} For $\rho_0$ this gives $\min(D, D_*) \le c - \Re\rho_0 < D_*$, so $D < D_*$. A pole $\rho$ nearest to $c$ satisfies $D = |c - \rho| \ge c - \Re\rho \ge D$. So equality holds, $\rho$ is real, and $\rho = \beta = c - D$; in particular $\beta$ is the only pole at distance $D$ from $c$. Its residue $\operatorname{Res}_\beta$ is positive by the \hyperref[8JS7]{corollary on real poles}. Choose $r$ with $D < r < D_*$ such that $\beta$ is the only pole in $\overline B(c, r)$. By Step 1, $A_k(c) = \operatorname{Res}_\beta D^{-k-1} + O(r^{-k})$, so with $y = 0$
\begin{align*}
|A_k(c)| + \Re A_k(c) &\ge 2\Re A_k(c) \\
&\ge 2\operatorname{Res}_\beta D^{-k-1} - O(r^{-k}) \ge \frac{\operatorname{Res}_\beta}{D}\, D^{-k}
\end{align*}
for all large $k$. This is the claim with $d = D$ and $C_1 = \operatorname{Res}_\beta/D$. Here the sign of $\operatorname{Res}_\beta$ is essential: if $\operatorname{Res}_\beta$ were negative, $|A_k(c)| + \Re A_k(c)$ could be small. See the \hyperref[8JT9]{picture of case (b)}.',
  body_html_cache = NULL, revision = revision + 1, updated_at = '2026-11-27 20:00:00', updated_by = 'claude'
WHERE id = 121;

-- 8JT6 statement
UPDATE results SET statement_tex = 'For $c > 0$ and $k \ge 1$ let $K_k(u) = u^k e^{-cu}/k!$ for $u \ge 0$, as in the \hyperref[8JT4]{concentration of the kernel}. Since $K_k(0) = 0$ and $\frac{d}{du} \ln K_k(u) = \frac ku - c$ for $u > 0$, the kernel increases up to $u = k/c$ and decreases after it. The graphs show $K_1$, $K_2$, $K_3$ for $c = 1$, with dashed lines at the peaks $u = 1, 2, 3$.
\includegraphics[width=1, alt=The kernels K_1, K_2, K_3 for c = 1, with dashed lines at their peaks]{/static/figures/gamma-kernel-a.svg}',
  statement_html_cache = NULL, revision = revision + 1, updated_at = '2026-11-27 20:00:00', updated_by = 'claude'
WHERE id = 137;

-- 8JT7 statement
UPDATE results SET statement_tex = 'Let $U > 0$ and $W = [U, \frac32 U]$, and let $c > 0$ and a positive integer $k$ satisfy $k/c = \frac54 U$, so that the kernel $K_k(u) = u^k e^{-cu}/k!$ peaks at the midpoint of $W$, as in the \hyperref[8JT2]{one-sided bound} up to rounding. Rescaled to peak value $1$, the kernel is
\[ \frac{K_k(u)}{K_k(k/c)} = \Bigl(\frac{cu}{k}\Bigr)^{k} e^{k - cu}, \]
which depends only on $k$ and $u/U$. The graphs show it for $k = 3, 30, 300$, with $W$ shaded. As $k$ grows, the kernel concentrates in $W$; part (ii) of the \hyperref[8JT4]{concentration of the kernel} is a quantitative version of this.
\includegraphics[width=1, alt=Rescaled kernels for k = 3, 30, 300 peaking at 5U/4, the midpoint of the shaded interval W]{/static/figures/gamma-kernel-b.svg}',
  statement_html_cache = NULL, revision = revision + 1, updated_at = '2026-11-27 20:00:00', updated_by = 'claude'
WHERE id = 138;

-- 8JT8 statement
UPDATE results SET statement_tex = 'This picture shows an illustrative configuration for case (a) in the proof of the \hyperref[8JT5]{lower bound for the Taylor coefficients}. The solid line is $\Re s=c$, the dashed line is $\Re s = \theta$, the strip between them is shaded, and $D_* = c-\theta$. Here the poles nearest to $c$ are $\rho_1$ and $\bar\rho_1$ (red), at the same distance $D$ (dashed circle), so their contributions to $A_k(c)$ may cancel. The point $z = c+iy$ is closer to $\rho_1$ (blue circle, radius $d$) than $c$ is to any pole, and $\rho_1$ is the only pole at distance $d$ from $z$. The picture is not to scale: in the application to the \hyperref[8JP5]{interval criterion}, $c \ge 200$, and all poles lie in $0 < \Re s < 1$.
\includegraphics[width=0.7, alt=Case a: the line Re s = c, the strip Re s greater than theta shaded, a blue circle around z touching the pole rho_1, and a dashed circle around c through rho_1 and its conjugate]{/static/figures/interval-criterion-a.svg}',
  statement_html_cache = NULL, revision = revision + 1, updated_at = '2026-11-27 20:00:00', updated_by = 'claude'
WHERE id = 139;

-- 8JT9 statement
UPDATE results SET statement_tex = 'This picture shows an illustrative configuration for case (b) in the proof of the \hyperref[8JT5]{lower bound for the Taylor coefficients}. Here $D$ is the distance from $c$ to the nearest pole (dashed circle), and every pole lies in $\Re s \le c - D$, left of the dotted line. The nearest pole is then the real pole $\beta = c - D$ (red), whose residue is positive. The picture is not to scale: in the application to the \hyperref[8JP5]{interval criterion}, $c \ge 200$, and all poles lie in $0 < \Re s < 1$.
\includegraphics[width=0.7, alt=Case b: the dashed circle around c touches the real pole beta, and all poles lie left of the dotted line Re s = c minus D]{/static/figures/interval-criterion-b.svg}',
  statement_html_cache = NULL, revision = revision + 1, updated_at = '2026-11-27 20:00:00', updated_by = 'claude'
WHERE id = 140;

-- 8JP5 proof
UPDATE proofs SET body_tex = '\emph{Idea.} The numbers $A_k(z) = \frac{(-1)^k}{k!}\mathcal H_\psi^{(k)}(z)$ are the Taylor coefficients of $w \mapsto \mathcal H_\psi(z - w)$. If $z$ has a unique nearest pole, at distance $d$, they grow like $d^{-k}$. Two parallel lemmas compare this growth on the line $\Re z=c$ with $(c-\theta)^{-k}$:
\begin{itemize}
\item the hypothesis caps it, by the \hyperref[8JT2]{one-sided bound for the Taylor coefficients};
\item a pole with $\Re\rho > \theta$ would exceed the cap, by the \hyperref[8JT5]{lower bound for the Taylor coefficients}.
\end{itemize}
Both lemmas bound the same quantity $|A_k(c+iy)| + \Re A_k(c)$, one from above and one from below. The upper bound works for this combination because it is at most $2\int_0^\infty g_+ K_k$, with $g(u) = \mathcal G_\psi(e^u)$, which involves only the positive part of $\mathcal G_\psi$: the hypothesis bounds $\mathcal G_\psi$ only from above.

\emph{The contradiction.} Suppose that some $\rho \in Z$ has $\Re\rho > \theta$. The hypothesis of the proposition is that of \ref{8JT2}; let $c_0$ be as there, fix a real $c \ge c_0$, and let $C$ and $K$ be as there. Since $c > 1$, \ref{8JT5} gives $y$, $C_1$, $d < c-\theta$ and $k_0$. For every $k \in K$ with $k \ge k_0$,
\[ C_1\, d^{-k} \le |A_k(c+iy)| + \Re A_k(c) \le C\, (c-\theta)^{-k}, \]
so $\bigl((c-\theta)/d\bigr)^{k} \le C/C_1$. Since $K$ is infinite and $(c-\theta)/d > 1$, this fails for large $k \in K$. Hence $\Re\rho \le \theta$ for every $\rho \in Z$.',
  body_html_cache = NULL, revision = revision + 1, updated_at = '2026-11-27 20:00:00', updated_by = 'claude'
WHERE id = 102;

-- 8JTA statement
UPDATE results SET statement_tex = 'Take $\psi = \mathbf 1$, the \hyperref[8JH4]{trivial character}, so that $L(s, \mathbf 1) = \zeta(s)$ and $o = 1$. The \hyperref[8JG8]{cyclic family} is $\mathcal C_{\mathbf 1} = \{\mathbf 1\}$ with weight $a_{\mathbf 1} = 1$, so the weighted sum is the \hyperref[8JF7]{smoothed prime sum} of the \hyperref[8JS9]{trivial character}:
\[ \mathcal G_{\mathbf 1}(x) = G_{\mathbf 1}(x) = \sum_{n \le x} \Lambda(n)\Bigl(\frac xn - 1\Bigr) - x\ln x + (1+\gamma)x. \]

\emph{Poles.} By \ref{8JS6} and \ref{8JN4}, the Mellin transform
\[ H_{\mathbf 1}(s) = -\frac{\zeta''(s)}{\zeta(s)}\,\frac{1}{s(s-1)} - \frac{1}{(s-1)^2} + \frac{1+\gamma}{s-1} \]
has a simple pole at each nontrivial zero $\rho$ of $\zeta$, with residue $-m(\rho)/(\rho(\rho-1))$, where $m(\rho)$ is the multiplicity. Moreover, \hyperref[8JUH]{none of these poles is real}. So for $\zeta$ only case (a) in the proof of the \hyperref[8JT5]{lower bound} can occur.

\emph{Explicit formula.} The \hyperref[8JUK]{residue theorem} gives, for $x \ge 1$,
\[ G_{\mathbf 1}(x) = \ln 2\pi - \sum_\rho \frac{x^\rho}{\rho(\rho - 1)} - \sum_{n \ge 1} \frac{x^{-2n}}{2n(2n+1)}, \]
where $\rho$ runs over the nontrivial zeros of $\zeta$, counted with multiplicity. Each zero $\rho = \beta + i\gamma$ contributes an oscillation $x^\rho = x^\beta e^{i\gamma\ln x}$ of size $x^\beta$.

\emph{Taylor coefficients.} Since $\int_1^\infty x^\rho\, x^{-s-1}\,dx = \frac{1}{s - \rho}$ for $\Re s > \Re\rho$, the \hyperref[8JS2]{Mellin transform} of the explicit formula is
\begin{align*}
H_{\mathbf 1}(s) = \frac{\ln 2\pi}{s} &- \sum_\rho \frac{1}{\rho(\rho-1)(s - \rho)} \\
&- \sum_{n \ge 1} \frac{1}{2n(2n+1)(s + 2n)}.
\end{align*}
Hence, for $\Re z > 1$ and $k \ge 0$, the coefficients $A_k(z) = \frac{(-1)^k}{k!}H_{\mathbf 1}^{(k)}(z)$ are
\begin{align*}
A_k(z) = \frac{\ln 2\pi}{z^{k+1}} &- \sum_\rho \frac{1}{\rho(\rho-1)(z - \rho)^{k+1}} \\
&- \sum_{n \ge 1} \frac{1}{2n(2n+1)(z + 2n)^{k+1}}.
\end{align*}
Each pole $p$ of $H_{\mathbf 1}$, with residue $\operatorname{Res}_p$, contributes $\operatorname{Res}_p/(z - p)^{k+1}$, so for large $k$ the poles nearest to $z$ dominate. The \hyperref[8JUP]{one-sided bound} uses the integral for $A_k$, and the \hyperref[8JUM]{lower bound} uses this series directly.

\emph{What the theorem says here.} For $\psi = \mathbf 1$ the \hyperref[8JK2]{interval estimate} only asks that $G_{\mathbf 1}(x) \le x^{1/2 + \varepsilon}$ on sparse intervals $[Y, Y^{3/2}]$. The \hyperref[8JUQ]{zeta interval criterion}, applied with $\theta=1/2+\varepsilon$ for every $0<\varepsilon<\frac12$, rules out nontrivial zeros to the right of the critical line. The functional equation then gives the Riemann hypothesis. Conversely, if the Riemann hypothesis holds, then $|x^\rho| = \sqrt x$ and $\rho(1 - \rho) = |\rho|^2$ for every zero, and $\sum_\rho \frac{1}{\rho(1-\rho)} = 2 + \gamma - \ln 4\pi \approx 0.0462$ \cite{Davenport}. With $\sum_{n \ge 1} \frac{1}{2n(2n+1)} = 1 - \ln 2 < 0.307$, the explicit formula then gives the much stronger two-sided bound
\[ |G_{\mathbf 1}(x) - \ln 2\pi| \le 0.0462\sqrt x + 0.307 \qquad (x \ge 1). \]

\emph{Graphs.} Panel (a) shows $G_{\mathbf 1}(x)$ for $1 \le x \le 10^7$, on a logarithmic $x$-axis, with this bound dashed.
\begin{center}
\textbf{(a)} $G_{\mathbf 1}(x)$ and the bound $\ln 2\pi \pm (0.0462\sqrt x + 0.307)$, for $1 \le x \le 10^7$
\end{center}
\includegraphics[width=1, alt=G_1(x) for x from 1 to 10 million on a logarithmic axis, oscillating with amplitude up to about 45, well inside the dashed curves ln 2 pi plus or minus (0.0462 sqrt x + 0.307)]{/static/figures/zeta-smoothed-sum.svg}
Panel (b) shows $(G_{\mathbf 1}(x) - \ln 2\pi)/\sqrt x$ for $10 \le x \le 10^7$, together with the explicit formula cut off after the first zero pair $\frac12 \pm 14.1347\,i$, which is a pure wave in $\ln x$, and after the first ten zero pairs, which already follows the data closely.
\begin{center}
\textbf{(b)} $\bigl(G_{\mathbf 1}(x) - \ln 2\pi\bigr)/\sqrt x$ and the explicit formula with the first one and ten zero pairs, for $10 \le x \le 10^7$
\end{center}
\includegraphics[width=1, alt=The normalized smoothed sum oscillating with size about 0.01 to 0.02, the first zero pair giving a pure wave and the first ten zero pairs following the data closely]{/static/figures/zeta-oscillation.svg}
Panel (c) shows $|A_k(\frac32 + iy)|$ for $k = 0, 1, 2, 3$ and $0 \le y \le 50$, on a logarithmic scale; the dotted lines mark the heights $\gamma$ of the zeros $\frac12 + i\gamma$. Here $c - \frac12 = 1$, so at $y = \gamma$ the zero $\rho = \frac12 + i\gamma$ contributes a term of size $1/|\rho|^2$ for every $k$, while the terms of the farther poles shrink as $k$ grows. For $k = 0$ and $1$ the pole at $s = 0$, with its comparatively large residue $\ln 2\pi \approx 1.84$, still dominates, and the zeros only make small dents. From $k = 2$ on, peaks of height about $1/|\rho|^2$ appear at the zeros. A zero $\beta + i\gamma$ with $\beta > \frac12$ would instead give peaks growing like $(\frac32 - \beta)^{-k}$, which is what the \hyperref[8JT5]{lower bound} detects.
\begin{center}
\textbf{(c)} $|A_k(\frac32 + iy)|$ for $k = 0, 1, 2, 3$ and $0 \le y \le 50$; dotted lines at the zero heights $\gamma$
\end{center}
\includegraphics[width=1, alt=The absolute values of A_0 to A_3 on the line Re s = 3/2 for y from 0 to 50 on a logarithmic scale, with peaks at the heights of the zeros of zeta appearing from k = 2 on]{/static/figures/zeta-taylor-coefficients.svg}',
  statement_html_cache = NULL, revision = revision + 1, updated_at = '2026-11-27 20:00:00', updated_by = 'claude'
WHERE id = 141;

-- 8JUM statement
UPDATE results SET statement_tex = 'Let $0<\theta<1$, and suppose a nontrivial zero $\rho_0$ of $\zeta$ satisfies $\Re\rho_0>\theta$. Let $A_k$ be the Taylor coefficients of $H_{\mathbf 1}$ in the \hyperref[8JTA]{zeta example}. For every real $c>1$ there are a real $y$, a constant $C_1>0$, a real $d$ with $0<d<c-\theta$, and a nonnegative integer $k_0$ such that for every integer $k\ge k_0$,
$$
|A_k(c+iy)|+\Re A_k(c)\ge C_1\,d^{-k}.
$$',
  statement_html_cache = NULL, revision = revision + 1, updated_at = '2026-11-27 20:00:00', updated_by = 'claude'
WHERE id = 145;

-- 8JUM proof
UPDATE proofs SET body_tex = '\emph{Idea.} Choose $z=c+iy$ whose nearest pole is closer to $z$ than any pole is to $c$. The corresponding term of the explicit series dominates both the rest of $A_k(z)$ and the whole of $A_k(c)$.

\emph{(1)} \textbf{The residues in the explicit series are absolutely summable.} Let $P$ consist of the distinct nontrivial zeros of $\zeta$ together with $0$ and the negative even integers. From the \hyperref[8JTA]{formula for $A_k$}, for $\Re z>1$,
$$
A_k(z)=\sum_{p\in P}\frac{\operatorname{Res}_p}{(z-p)^{k+1}},
$$
where $\operatorname{Res}_p$ is the residue of $H_{\mathbf 1}$ at $p$. In particular $\operatorname{Res}_0=\ln 2\pi$, $\operatorname{Res}_{-2n}=-1/(2n(2n+1))$, and $\operatorname{Res}_\rho=-m(\rho)/(\rho(\rho-1))$ for a nontrivial zero of multiplicity $m(\rho)$. Thus $B=\sum_{p\in P}|\operatorname{Res}_p|<\infty$ by absolute convergence of the \hyperref[8JUK]{explicit formula} at $x=1$.

\emph{(2)} \textbf{A point on $\Re z=c$ can get closer to a single pole than $c$ is to any pole.} Fix $c>1$ and let $D=\min_{p\in P}|c-p|$. This minimum exists by local finiteness. Put $a_0=c-\Re\rho_0<c-\theta$. If $a_0<D$, take $p=\rho_0$. If $D\le a_0$, take a pole $p$ at distance $D$ from $c$. Since $D<c$, this $p$ cannot be a nonpositive real pole. It is a nontrivial zero and hence \hyperref[8JUH]{nonreal}, so $c-\Re p<|c-p|=D$. In both cases,
$$
c-\Re p<\min(D,c-\theta).
$$

For $y$ in a sufficiently small closed interval of positive length around $\operatorname{Im}p$, we still have $|c+iy-p|<\min(D,c-\theta)$. Only finitely many poles can be this close to the resulting compact segment. Two poles with different imaginary parts tie in distance for at most one $y$, since the difference of their squared distances is affine with nonzero slope. Two poles with the same imaginary part have different horizontal distances because both lie to the left of the line. Choose $y$ in the interval away from the finitely many ties. Then $z=c+iy$ has a unique nearest pole $p_*$, at distance $d<\min(D,c-\theta)$.

\emph{(3)} \textbf{Estimate the nearest-pole term, the remaining terms at $z$, and the real-axis contribution separately.}
By local finiteness, the following distances are attained:
$$
r=\min_{p\in P\setminus\{p_*\}}|z-p|,
\qquad D_1=\min_{p\in P\setminus\{0\}}|c-p|.
$$
The nearest pole to $z$ is unique, so $r>d$. Also $D_1\ge D>d$.

\begin{enumerate}
\item[(a)] \textbf{The nearest pole at $z$.} Its contribution has absolute value
$$
\left|\frac{\operatorname{Res}_{p_*}}{(z-p_*)^{k+1}}\right|
= |\operatorname{Res}_{p_*}|\,d^{-k-1}.
$$

\item[(b)] \textbf{The other poles at $z$.} Use $|z-p|\ge r$ for every $p\ne p_*$:
\begin{align*}
\left|\sum_{p\ne p_*}\frac{\operatorname{Res}_p}{(z-p)^{k+1}}\right|
&\le \sum_{p\ne p_*}\frac{|\operatorname{Res}_p|}{|z-p|^{k+1}}\\
&\le (B-|\operatorname{Res}_{p_*}|)\,r^{-k-1}.
\end{align*}

\item[(c)] \textbf{The real-axis contribution.} The pole at $0$ contributes $\operatorname{Res}_0 c^{-k-1}>0$. For every other pole, use $\Re w\ge -|w|$ and $|c-p|\ge D_1$:
\begin{align*}
\Re A_k(c)
&\ge \operatorname{Res}_0 c^{-k-1}
 -\sum_{p\ne 0}\frac{|\operatorname{Res}_p|}{|c-p|^{k+1}}\\
&\ge \operatorname{Res}_0 c^{-k-1}-(B-\operatorname{Res}_0)\,D_1^{-k-1}.
\end{align*}
\end{enumerate}

Relative to the term in (a), the two possible losses are bounded by
$$
\frac{B-|\operatorname{Res}_{p_*}|}{|\operatorname{Res}_{p_*}|}\left(\frac{d}{r}\right)^{k+1},
\qquad
\frac{B-\operatorname{Res}_0}{|\operatorname{Res}_{p_*}|}\left(\frac{d}{D_1}\right)^{k+1}.
$$
Both ratios tend to zero. Choose a nonnegative integer $k_0$ so that each is at most $1/4$ for every integer $k\ge k_0$. For these $k$, the reverse triangle inequality and (a)–(c) give
\begin{align*}
|A_k(z)|+\Re A_k(c)
&\ge |\operatorname{Res}_{p_*}|\,d^{-k-1}-(B-|\operatorname{Res}_{p_*}|)\,r^{-k-1}\\
&\quad +\operatorname{Res}_0 c^{-k-1}-(B-\operatorname{Res}_0)\,D_1^{-k-1}\\
&\ge \frac{|\operatorname{Res}_{p_*}|}{2d}\,d^{-k}+\operatorname{Res}_0 c^{-k-1}.
\end{align*}',
  body_html_cache = NULL, revision = revision + 1, updated_at = '2026-11-27 20:00:00', updated_by = 'claude'
WHERE id = 125;

-- 8JUP statement
UPDATE results SET statement_tex = 'Let $0<\theta<1$. Suppose that for every real $Y_0\ge 1$ there is a real $Y\ge Y_0$ such that
$$
G_{\mathbf 1}(x)\le x^\theta
\qquad \text{for every } x\in[Y,Y^{3/2}].
$$
Let $A_k$ be the Taylor coefficients of $H_{\mathbf 1}$ in the \hyperref[8JTA]{zeta example}. There is a real $c_0>2$ such that for every real $c\ge c_0$ there are a constant $C>0$ and an infinite set $K$ of positive integers with the following property. For every $k\in K$ and every real $y$,
$$
|A_k(c+iy)|+\Re A_k(c)\le C(c-\theta)^{-k}.
$$',
  statement_html_cache = NULL, revision = revision + 1, updated_at = '2026-11-27 20:00:00', updated_by = 'claude'
WHERE id = 146;

-- 8JUP proof
UPDATE proofs SET body_tex = 'The \hyperref[8JTA]{explicit formula} gives $|G_{\mathbf 1}(x)|\le Bx$ for some $B>0$ and every $x\ge 1$. Indeed, each power $x^\rho$ has modulus at most $x$, and the coefficients of all the terms are \hyperref[8JUK]{absolutely summable}.

Put $g(u)=G_{\mathbf 1}(e^u)$ and $g_+(u)=\max(g(u),0)$. Let $c_0$ be the threshold in the \hyperref[8JT4]{kernel concentration estimate}, and fix $c\ge c_0$. For each $Y>1$ in the hypothesis put $U=\ln Y$ and choose
$$
W=[U,\tfrac32 U],\qquad k=\bigl\lceil\tfrac54c U\bigr\rceil,
\qquad K_k(u)=\frac{u^k e^{-cu}}{k!}.
$$
This puts the peak of $K_k$ at the midpoint of $W$, up to rounding. By the \hyperref[8JT3]{Laplace integral for the Taylor coefficients},
$A_k(c+iy)=\int_0^\infty g(u)K_k(u)e^{-iyu}\,du$.
Since $g$ is real, the following holds for every real $y$:
\begin{align*}
|A_k(c+iy)|+\Re A_k(c)
&\le 2\int_0^\infty g_+(u) K_k(u)\,du \\
&\le 2\int_W e^{\theta u}K_k(u)\,du
  +2B\int_{[0,\infty)\setminus W} e^{2u}K_k(u)\,du \\
&\le 2(c-\theta)^{-k-1}+4Bc^{-k} \\
&\le (2+4B)(c-\theta)^{-k}.
\end{align*}
The second line uses the interval bound on $W$ and $|g(u)|\le Be^u\le Be^{2u}$ elsewhere. The third line uses both parts of the kernel estimate. The eligible $Y$ are unbounded, so the resulting set $K$ of integers $k$ is infinite.',
  body_html_cache = NULL, revision = revision + 1, updated_at = '2026-11-27 20:00:00', updated_by = 'claude'
WHERE id = 126;

-- 8JUQ proof
UPDATE proofs SET body_tex = 'Suppose a nontrivial zero has real part greater than $\theta$. Fix a real $c\ge c_0$ as in the \hyperref[8JUP]{one-sided bound}, with constant $C$ and infinite set $K$. The \hyperref[8JUM]{lower bound} gives $y$, $C_1>0$, $0<d<c-\theta$, and $k_0$. For each $k\in K$ with $k\ge k_0$,
$$
C_1\,d^{-k}\le |A_k(c+iy)|+\Re A_k(c)
\le C(c-\theta)^{-k}.
$$
This would bound $\bigl((c-\theta)/d\bigr)^k$ by $C/C_1$ on an unbounded set of $k$, even though $(c-\theta)/d>1$.',
  body_html_cache = NULL, revision = revision + 1, updated_at = '2026-11-27 20:00:00', updated_by = 'claude'
WHERE id = 127;

